func (ps PackageFixStatuses) Sort() {
	sort.Slice(ps, func(i, j int) bool {
		if ps[i].Name != ps[j].Name {
			return ps[i].Name < ps[j].Name
		}
		return ps[j].FixedIn < ps[i].FixedIn
